import{_ as e,o as a,c as i,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"project/roadmap.md","filePath":"project/roadmap.md"}'),o={name:"project/roadmap.md"};function r(l,t,s,d,c,u){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><h2 id="what-s-built-and-tested-now" tabindex="-1">What&#39;s built and tested now <a class="header-anchor" href="#what-s-built-and-tested-now" aria-label="Permalink to &quot;What&#39;s built and tested now&quot;">​</a></h2><ul><li>Walletless flow architecture (no wallet, address, or gas fee for either party)</li><li>Real Hedera testnet integration: HCS anchoring, HTS transfers, Mirror Node verification</li><li>Compliance, quote, and routing-decision anchoring with tamper detection</li><li>Real, live liquidity-based chain routing (Hedera preferred, with a researched, cited fallback)</li><li>22 passing unit tests</li></ul><h2 id="deliberately-not-built-yet-and-why" tabindex="-1">Deliberately not built yet, and why <a class="header-anchor" href="#deliberately-not-built-yet-and-why" aria-label="Permalink to &quot;Deliberately not built yet, and why&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Why it&#39;s future work, not a shortcut taken now</th></tr></thead><tbody><tr><td><strong>Ethereum / Solana / Base / BNB Chain execution</strong></td><td>Requires funded testnet accounts and SDKs for four chains, real integration work, not a coding shortcut. The <em>routing decision</em> already accounts for all four (see <a href="./../architecture/settlement-layer.html">Settlement Layer</a>); only execution is pending.</td></tr><tr><td><strong>Full CCTP / Circle Mint bridging</strong></td><td>Depends on which CCTP version supports which chain at a given time, a fast-moving external dependency, verified at build time rather than hardcoded.</td></tr><tr><td><strong>Real partner integration</strong></td><td><code>PARTNER_CHAIN_SUPPORT</code> is illustrative scaffolding. Onboarding an actual sandbox payout partner is a business/legal step, not an engineering one.</td></tr><tr><td><strong>Production licensing</strong></td><td>This project is legal <em>as designed</em>, non-custodial, orchestration-only. Any future step toward holding funds (e.g., our own stablecoin issuance, direct custody) would require CASP/PI/EMI authorisation and is explicitly out of scope.</td></tr></tbody></table><h2 id="explicitly-out-of-scope-permanently" tabindex="-1">Explicitly out of scope, permanently <a class="header-anchor" href="#explicitly-out-of-scope-permanently" aria-label="Permalink to &quot;Explicitly out of scope, permanently&quot;">​</a></h2><ul><li>Trading, DEX integration, or any activity requiring custody of a client&#39;s crypto-assets, this would require a <strong>different legal entity</strong> with its own CASP authorisation, not an extension of this one. See <a href="./../legal/why-this-is-legal.html">Why This Is Legal</a>.</li><li>Issuing our own stablecoin. EMT issuance is legally reserved to EMIs and credit institutions.</li></ul>',7)])])}const g=e(o,[["render",r]]);export{p as __pageData,g as default};
